    #[test] fn decodes_what_pythons_gzip_made() {
        assert_eq!(gunzip(GZ_TEXT, 1 << 20).unwrap(), b"hello world ".repeat(50));
        assert_eq!(gunzip(GZ_EMPTY, 1 << 20).unwrap(), b"");
        assert_eq!(gunzip(GZ_RAND, 1 << 20).unwrap().len(), 3000);            // stored blocks; the CRC in the trailer proves the content
        let mixed: Vec<u8> = (0..20000u32).map(|i| ((i * 7 + (i >> 5)) % 251) as u8).chain(b"abc".repeat(3000)).collect();
        assert_eq!(gunzip(GZ_MIXED, 1 << 20).unwrap(), mixed);               // dynamic Huffman blocks with long matches
    }
    #[test] fn limits_and_corruption_are_errors() {
        assert_eq!(gunzip(GZ_TEXT, 100).unwrap_err(), "output exceeds the limit");
        let mut bad = GZ_MIXED.to_vec(); let n = bad.len(); bad[n - 6] ^= 0xFF; assert!(gunzip(&bad, 1 << 20).is_err());        // trailer CRC
        let mut cut = GZ_MIXED.to_vec(); cut.truncate(cut.len() / 2); assert!(gunzip(&cut, 1 << 20).is_err());
        assert!(gunzip(b"not gzip at all, just text.....", 1 << 20).is_err());
    }
    #[test] fn inflate_never_panics_on_garbage() {
        let mut x: u64 = 0x2545F4914F6CDD1D; let mut rnd = move || { x ^= x << 13; x ^= x >> 7; x ^= x << 17; x };
        for i in 0..30000 {
            let mut b = if i % 3 == 0 { (0..(rnd() % 300) as usize).map(|_| rnd() as u8).collect::<Vec<u8>>() } else { [GZ_MIXED, GZ_TEXT, GZ_RAND][(rnd() % 3) as usize].to_vec() };
            for _ in 0..(rnd() % 5) { if b.is_empty() { break; } let j = (rnd() as usize) % b.len(); match rnd() % 3 { 0 => b[j] = rnd() as u8, 1 => { b.remove(j); }, _ => b.truncate(j) } }
            let _ = gunzip(&b, 1 << 20); let _ = inflate(&b, 1 << 20);
        }
    }
